}

selection-sort.code:
#include <stdio.h>
int main(void) {
    int a[100], n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100) return 1;
    for (int i = 0; i < n; ++i)
        if (scanf("%d", &a[i]) != 1) return 1;
    for (int i = 0; i < n - 1; ++i) {
        int min_index = i;
        for (int j = i + 1; j < n; ++j)
            if (a[j] < a[min_index]) min_index = j;
        if (min_index != i) {
            int temp = a[i];
            a[i] = a[min_index];
            a[min_index] = temp;
        }
    }
    for (int i = 0; i < n; ++i)
        printf("%d%s", a[i], i == n - 1 ? "\n" : " ");
    return 0;
}

